function Footer(){return html`<footer class="bg-primary text-primary-foreground mt-10"><div class="container pt-10 pb-28 md:pb-10"><div class="grid sm:grid-cols-2 md:grid-cols-4 gap-8"><div><span class="flex items-center gap-2 mb-3"><img src="https://pin.it/4fU1pcCXc" width="30" height="30" alt="" aria-hidden="true" class="rounded-[9px] object-cover shrink-0"/><span class="font-display text-2xl font-bold">Galti</span></span><p class="text-sm text-primary-foreground/75 leading-relaxed">Your neighbourhood mini-mart in Elgonview, Eldoret, now with delivery.</p></div>${[['Shop',[['All products','shop'],['Today’s deals','deals'],['Drinks','cat-beverages'],['Pantry','cat-pantry'],['Snacks','cat-snacks']]],['Help',[['My orders','orders'],['Wishlist','wishlist'],['About us','about']]],['Visit us',[['Elgonview, Eldoret',''],['Open '+SET.hours,''],['WhatsApp us','wa'],['Staff login','admin']]]].map(c=>html`<div key=${c[0]}><h4 class="font-display text-base font-semibold mb-3">${c[0]}</h4><ul class="list-none p-0 m-0 space-y-1 text-sm text-primary-foreground/80">${c[1].map(l=>html`<li key=${l[0]}>${l[1]==='wa'?html`<a class="inline-flex items-center min-h-[36px] underline-offset-2 hover:underline" target="_blank" rel="noopener" href=${'https://wa.me/'+WA}>${l[0]}</a>`:l[1]?html`<a class="inline-flex items-center min-h-[36px] hover:underline" href=${'#'+l[1]}>${l[0]}</a>`:html`<span class="inline-flex items-center min-h-[28px]">${l[0]}</span>`}</li>`)}</ul></div>`)}</div><div class="mt-8 pt-5 border-t border-primary-foreground/15 flex flex-wrap items-center justify-between gap-3 text-xs text-primary-foreground/60"><span>Delivery areas: ${AREAS.join(', ')}</span><span>M-Pesa · Card · Cash on delivery</span></div><p class="mt-3 text-xs text-primary-foreground/50">© ${new Date().getFullYear()} Galti Mini-Mart</p></div></footer>`}
